-- ===== Fact (30) =====
('luteal', 'fact', 'Fase luteal dimulai', 'Setelah ovulasi, tubuh masuk fase luteal sekitar 14 hari. Progesteron naik memberikan vibe berbeda dari folikular.', null, 1),
('luteal', 'fact', 'Progesteron dominan', 'Hormon utama luteal. Stabilkan endometrium jika konsepsi terjadi. Jika tidak, drop memicu haid.', null, 2),
('luteal', 'fact', 'BBT tetap tinggi', 'BBT tetap tinggi sampai akhir luteal. Drop tajam menjadi sinyal haid besoknya.', null, 3),
('luteal', 'fact', 'PMS akhir luteal', 'Premenstrual Syndrome biasanya muncul 7 sampai 10 hari sebelum haid. Pergeseran hormonal jadi penyebab biologis.', null, 4),
('luteal', 'fact', 'Energi menurun bertahap', 'Berbeda dari folikular high-energy, luteal pace lebih lambat. Tubuh bergeser fokus ke persiapan recovery.', null, 5),
('luteal', 'fact', 'Cravings dijelaskan', 'Drop progesteron plus serotonin memicu craving karbohidrat manis. Tubuh mencari prekursor serotonin.', null, 6),
('luteal', 'fact', 'Bloating fisiologis', 'Progesteron memperlambat motilitas usus, menyebabkan konstipasi dan bloat. Plus retensi air. Keduanya sementara.', null, 7),
('luteal', 'fact', 'Payudara sensitif umum', 'Progesteron memicu proliferasi duktal di payudara. Kembali normal saat haid mulai.', null, 8),
('luteal', 'fact', 'Mood lability', 'Pergeseran hormonal memengaruhi neurotransmitter. Mood swing valid secara biologis, bukan emosi yang dilebih-lebihkan.', null, 9),
('luteal', 'fact', 'Tidur sering terganggu', 'BBT tinggi mengganggu arsitektur tidur. Bangun lebih sering, tidur lebih ringan.', null, 10),
('luteal', 'fact', 'Jerawat hormonal', 'Progesteron dan androgen rebalance meningkatkan produksi sebum. Jerawat akhir luteal umum.', null, 11),
('luteal', 'fact', 'Spike kecemasan', 'Sistem GABA dipengaruhi metabolit progesteron. Sebagian merasakan kecemasan naik khusus di luteal.', null, 12),
('luteal', 'fact', 'Sakit kepala hormonal', 'Drop estrogen akhir luteal memicu menstrual migraine. Bedakan dengan tension headache.', null, 13),
('luteal', 'fact', 'Sensitivitas insulin turun', 'Tubuh kurang efisien memproses karbo dibanding folikular. Steady protein dan serat lebih ideal.', null, 14),
('luteal', 'fact', 'Kortisol elevated', 'Respons stres heightened di luteal. Trigger yang sama terasa more stressful dibanding folikular.', null, 15),
('luteal', 'fact', 'PMDD bentuk parah', 'Premenstrual Dysphoric Disorder adalah PMS parah yang mengganggu fungsi harian. 3 sampai 8 persen perempuan menstruasi. Diakui DSM-5.', null, 16),
('luteal', 'fact', 'Memori shift halus', 'Recall sedikit lebih lambat dibanding folikular. Memori jangka pendek tidak terpengaruh. Variabel per individu.', null, 17),
('luteal', 'fact', 'Ambang nyeri turun', 'Drop estrogen menyebabkan nyeri terasa lebih intens. Same level kram bisa dirasakan berbeda di scale.', null, 18),
('luteal', 'fact', 'Libido turun bertahap', 'Berlawanan dengan folikular. Sebagian merasakan drop tajam, lainnya bertahap. Keduanya normal.', null, 19),
('luteal', 'fact', 'Suhu tubuh lebih hangat', 'Sering perlu kamar tidur lebih dingin. Layered bedding memudahkan adjusting suhu.', null, 20),
('luteal', 'fact', 'Tanda haid mendekat', '4 sampai 5 hari pre-haid: spotting ringan, lendir coklat atau krem, payudara sensitif puncak. Tubuh menyelesaikan siklus.', null, 21),
('luteal', 'fact', 'Serviks turun dan menutup', 'Serviks turun, mengeras, menutup di luteal. Berbalik dari fase ovulasi.', null, 22),
('luteal', 'fact', 'Asal kata luteal', 'Dari corpus luteum (yellow body), sisa follicle yang memproduksi progesteron.', null, 23),
('luteal', 'fact', 'Treatment PMDD', 'SSRI (antidepressant), kontrasepsi hormonal, atau intervensi lifestyle. Konsultasikan profesional kesehatan.', null, 24),
('luteal', 'fact', 'PMS bukan total negatif', 'Hingga 75 persen mengalami gejala PMS, biasanya ringan. Severe (PMDD) hanya subset kecil. Tanpa stigma.', null, 25),
('luteal', 'fact', 'Tahap sekretori', 'Endometrium memasuki tahap sekretori: kelenjar membesar, mengeluarkan glikogen sebagai persiapan implantasi.', null, 26),
('luteal', 'fact', 'Hot flash mini', 'Sebagian merasakan hot flash mini di luteal akibat fluktuasi hormonal. Mirip pra-menopause tetapi sementara.', null, 27),
('luteal', 'fact', 'Nausea mungkin', 'Sebagian merasakan mual ringan akhir luteal. Terkait progesteron tinggi yang juga dialami di kehamilan awal.', null, 28),
('luteal', 'fact', 'Pertumbuhan rambut wajah', 'Androgen relatif lebih tinggi vs estrogen di akhir luteal. Bisa muncul jerawat atau rambut wajah halus.', null, 29),
('luteal', 'fact', 'Migrain pre-haid', 'Sekitar 60 persen perempuan dengan migrain mengalami episode pre-haid. Disebut menstrual migraine.', null, 30),

-- ===== Tip (25) =====
('luteal', 'tip', 'Olahraga lebih ringan', 'Cardio LISS atau yoga lebih dari HIIT. Tubuh lebih efisien di steady-state phase ini.', null, 50),
('luteal', 'tip', 'Magnesium untuk PMS', '300 sampai 400 mg per hari. Membantu mood, kram, dan tidur. Bentuk glycinate gentle untuk lambung.', null, 51),
('luteal', 'tip', 'Vitamin B6', 'Hingga 100 mg per hari membantu PMS mood. Konsultasikan dokter untuk konsumsi jangka panjang.', null, 52),
('luteal', 'tip', 'Kurangi garam', 'Sodium tinggi memperparah retensi air dan bloat. Kurangi makanan olahan asin.', null, 53),
('luteal', 'tip', 'Tingkatkan serat', 'Serat untuk motilitas. 25 sampai 30 g per hari mencegah konstipasi luteal. Apel, oat, lentil.', null, 54),
('luteal', 'tip', 'Seed cycling', 'Konsumsi flax dan pumpkin seeds di paruh luteal. Anekdotal practice, sebagian melaporkan perbaikan subjektif.', null, 55),
('luteal', 'tip', 'Restorative yoga', 'Forward folds, child pose, supine twist. Menenangkan sistem saraf simpatik.', null, 56),
('luteal', 'tip', 'Prioritas tidur ekstra', 'Tubuh terganggu ekstra. Tidur lebih awal, kamar gelap, jadwal konsisten.', null, 57),
('luteal', 'tip', 'Hidrasi dengan elektrolit', 'Air biasa kadang tidak cukup. Air kelapa atau pinch garam plus lemon membantu.', null, 58),
('luteal', 'tip', 'Batas kafein', 'Kafein memperparah cemas dan mengganggu tidur. Cap 200 mg per hari di paruh luteal.', null, 59),
('luteal', 'tip', 'Atur jadwal cermat', 'Presentasi besar? Jadwalkan lebih awal di luteal (pre-PMS). Simpan luteal akhir untuk tugas low cognitive.', null, 60),
('luteal', 'tip', 'Comfort food intentional', 'Craving karbo? Pilih karbohidrat kompleks (oat, quinoa, ubi). Energi sustained lebih dari spike gula.', null, 61),
('luteal', 'tip', 'Turunkan ekspektasi', 'Tidak apa jika kurang produktif di luteal akhir. Sesuaikan ekspektasi dengan kapasitas fase ini.', null, 62),
('luteal', 'tip', 'Boundaries firm', 'Tidak diperbolehkan jika kapasitas tidak ada. Saying yes saat low capacity hanya menumbuhkan resentment.', null, 63),
('luteal', 'tip', 'Self-care non-negotiable', 'Mandi hangat, jurnal, gentle yoga. Tandai kalender, luteal self-care adalah janji dengan diri.', null, 64),
('luteal', 'tip', 'Paparan sinar matahari', '10 sampai 15 menit sinar pagi membantu mood dan ritme tidur. Sangat membantu di luteal akhir.', null, 65),
('luteal', 'tip', 'Batasi berita dan media sosial', 'Konten kortisol-amplifying dihindari di luteal akhir. Konsumsi media sosial dan berita secara mindful.', null, 66),
('luteal', 'tip', 'Hubungi orang aman', 'Bicara dengan teman atau keluarga yang Kamu percayai. Koneksi mengimbangi keberatan luteal.', null, 67),
('luteal', 'tip', 'Konsumsi triptofan', 'Pisang, kalkun, telur, kacang. Triptofan adalah prekursor serotonin yang sering kurang di luteal.', null, 68),
('luteal', 'tip', 'Latihan napas dalam', 'Breathing exercise 4-7-8 (inhale 4s, hold 7s, exhale 8s) mengaktifkan parasimpatik. Lakukan 4 siklus saat cemas.', null, 69),
('luteal', 'tip', 'Cuci muka 2 kali sehari', 'Sebum naik di akhir luteal. Cleanse pagi dan malam, hindari over-washing yang justru memicu lebih banyak minyak.', null, 70),
('luteal', 'tip', 'Konsumsi kalsium', '1200 mg kalsium per hari (dari makanan dan suplemen) dapat mengurangi keparahan PMS sesuai studi 2017.', null, 71),
('luteal', 'tip', 'Pijat perut bawah', 'Pijat perut searah jarum jam dengan minyak hangat 5 sampai 10 menit membantu meredakan tegangan.', null, 72),
('luteal', 'tip', 'Refleksi mingguan', 'Sebelum mood luteal puncak, refleksikan minggu lalu. Kapasitas mental masih cukup untuk evaluasi jujur.', null, 73),
('luteal', 'tip', 'Hindari keputusan besar', 'Jika memungkinkan, tunda keputusan major (pindah kerja, putus hubungan) sampai post-haid. Klaritas akan membaik.', null, 74),

-- ===== Trivia (8) =====
('luteal', 'trivia', '14-day luteal default', 'ACOG: fase luteal 12 sampai 16 hari. Jika cycle 28, ovulasi hari 14. Cycle 35, ovulasi hari 21.', null, 90),
('luteal', 'trivia', 'PMS coined 1953', 'Istilah Premenstrual Tension oleh Greene dan Dalton tahun 1953. PMS resmi DSM tahun 1994 (PMDD).', null, 91),
('luteal', 'trivia', 'Mengapa craving asin', 'Aldosterone fluktuasi di luteal mengubah water balance. Tubuh mencari asin sebagai kompensasi.', null, 92),
('luteal', 'trivia', 'Coklat kenapa craving', 'Dark chocolate memiliki magnesium, prekursor serotonin, dan anti-inflamasi. Tubuh secara intuitif tahu.', null, 93),
('luteal', 'trivia', 'PMS pada hewan', 'Beberapa hewan menunjukkan perubahan perilaku pre-haid, seperti primata, anjing in heat. Hormon lintas spesies.', null, 94),
('luteal', 'trivia', 'Penemu corpus luteum', 'Marcello Malpighi mendeskripsikan corpus luteum tahun 1697. Diberi nama yellow body karena warnanya kuning.', null, 95),
('luteal', 'trivia', 'PMS pertama dikatalogkan', 'Robert Frank tahun 1931 pertama mempublikasi paper ilmiah tentang premenstrual symptom. Disebut sebagai premenstrual tension.', null, 96),
('luteal', 'trivia', 'Korelasi PMS dan musim', 'Studi menunjukkan PMS lebih parah di musim dingin akibat kurang vitamin D dari sinar matahari.', null, 97),

